 const addProductByBarcode=(raw:string):ScanResult=>{
  const barcode=normalizeBarcode(raw);
  if(!barcode)return {kind:'warning',message:'Informe um código válido.'};
  const matches=findBarcodeProducts(products,barcode);
  if(matches.length===0)return {kind:'warning',message:'Produto não cadastrado.',unknownCode:barcode};
  if(matches.length>1)return {kind:'warning',message:'Código duplicado em cadastros existentes. Corrija o catálogo antes de vender.'};
  const product=matches[0];
  if(!product.active)return {kind:'warning',message:'Produto inativo: '+product.title};
  const inCart=cart.find(line=>line.productId===product.id)?.quantity||0;
  if(inCart+1>product.stock)return {kind:'warning',message:'Estoque insuficiente para '+product.title+'. Disponível: '+product.stock+'.'};
  setCart(old=>{
    const existing=old.find(line=>line.productId===product.id);
    return existing?old.map(line=>line.productId===product.id?{...line,quantity:line.quantity+1}:line):[...old,{productId:product.id,title:product.title,sku:product.sku,quantity:1,price:product.price,cost:product.cost,unit:product.unit}];
  });
  return {kind:'success',message:product.title+' adicionado ao carrinho ('+(inCart+1)+' '+product.unit+').'};
 };
 const handleBarcodeDetected=(raw:string):ScanResult=>{
  const barcode=normalizeBarcode(raw);
  if(scannerMode==='product'){
    setForm(old=>({...old,barcode}));
    setScannerMode(null);
    const duplicate=findBarcodeProducts(products,barcode).find(p=>p.id!==editingId);
    return {kind:duplicate?'warning':'success',message:duplicate?'Código já cadastrado para '+duplicate.title:'Código preenchido: '+barcode};
  }
  return addProductByBarcode(barcode);
 };
