 const revenues=confirmed.reduce((t,o)=>t+orderTotal(o),0),cogs=confirmed.reduce((t,o)=>t+orderCost(o),0),profit=round(revenues-cogs),paidSales=confirmed.reduce((t,o)=>t+n(o.paid),0),receivable=confirmed.reduce((t,o)=>t+openAmount(o),0);
