 const saveSupplier=(event:FormEvent)=>{event.preventDefault();if(!form.title?.trim())return;const found=suppliers.find(x=>x.id===editingId);const next:ERPSupplier={id:found?.id||erpId(),workspaceId,createdAt:found?.createdAt||new Date().toISOString(),title:form.title.trim(),document:form.document||'',phone:form.phone||'',email:form.email||'',contact:form.contact||'',address:form.address||'',notes:form.notes||''};modify(e=>({...e,suppliers:found?e.suppliers.map(x=>x.id===found.id?next:x):[...e.suppliers,next]}));close();notify('Fornecedor salvo.')};
