  {tab==='estoque'&&<><div className="erp-metrics erp-metrics-three">{keyMetric('SKUs cadastrados',String(products.length),'Itens no catálogo',Barcode)}{keyMetric('Estoque baixo',String(lowStock.length),lowStock.length?'Reposição necessária':'Estoque sem alertas',AlertCircle,false,lowStock.length?'warning':'positive')}{keyMetric('Saldo em custo',money(valueStock),'Valorização do estoque',PackageCheck)}</div><Block title="Alerta de reposição" caption="Produtos no limite ou abaixo do estoque mínimo">{lowStock.length?<DataTable rows={lowStock} columns={[{name:'Produto',cell:(p:ERPProduct)=>p.title},{name:'Estoque atual',cell:(p:ERPProduct)=><Tag tone="bad">{p.stock} {p.unit}</Tag>},{name:'Mínimo',cell:(p:ERPProduct)=>p.minimumStock},{name:'',cell:(p:ERPProduct)=><Btn onClick={()=>openAdjust(p)}>Ajustar estoque</Btn>}]}/>:<div className="erp-success"><CheckCircle2 size={18}/> Nenhum produto ativo abaixo do estoque mínimo.</div>}</Block><Block title="Livro de movimentações" caption="Histórico rastreável de entradas, saídas e ajustes">{movements.length?<DataTable rows={[...movements].reverse()} columns={[{name:'Data',cell:(x:any)=>dateShort(x.date)},{name:'Produto',cell:(x:any)=><b>{x.productTitle}</b>},{name:'Motivo',cell:(x:any)=>x.reason},{name:'Quantidade',cell:(x:any)=><Tag tone={x.delta>0?'good':'bad'}>{x.delta>0?'+':''}{x.delta}</Tag>}]}/>:<Empty title="Nenhuma movimentação" desc="Entradas e saídas aparecerão aqui ao registrar estoques, vendas e compras."/>}</Block></>}
