  {tab==='financeiro'&&<><div className="erp-metrics erp-metrics-three">{keyMetric('A receber',money(receivable+bills.filter(x=>x.type==='Receber').reduce((t,x)=>t+openAmount(x),0)),'Valores ainda não recebidos',HandCoins,false,(receivable+bills.filter(x=>x.type==='Receber').reduce((t,x)=>t+openAmount(x),0))>0?'warning':'neutral')}{keyMetric('A pagar',money(payable),'Pagamentos a realizar',CreditCard,false,payable>0?'warning':'neutral')}{keyMetric('Vendas já recebidas',money(paidSales),'Dinheiro recebido',CircleDollarSign,false,paidSales>0?'positive':'neutral')}</div><Block title="Títulos e contas" caption="Controle de pagamentos, recebimentos e vencimentos" action={<Btn primary onClick={()=>openBill()}><Plus size={16}/> Nova conta</Btn>}>{allDue.length?<DataTable rows={[...allDue].sort((a,b)=>a.dueDate.localeCompare(b.dueDate))} columns={[{name:'Descrição',cell:(x:any)=><div className="erp-cell-title"><b>{x.title}</b><small>{x.type}</small></div>},{name:'Vencimento',cell:(x:any)=>dateShort(x.dueDate)},{name:'Valor',cell:(x:any)=>money(x.amount)},{name:'Em aberto',cell:(x:any)=><b>{money(Math.max(0,x.amount-x.paid))}</b>},{name:'Situação',cell:(x:any)=><Tag tone={badgeTone(x.amount-x.paid<=.009?'Quitado':x.dueDate<erpDate()?'Vencida':'Em aberto')}>{x.amount-x.paid<=.009?'Quitado':x.dueDate<erpDate()?'Vencida':paidStatus(x.amount,x.paid)}</Tag>},{name:'Ações',cell:(x:any)=><RowActions>{x.amount-x.paid>.009&&<Btn onClick={()=>openPay(x.kind,x.sourceId)}>Registrar pagamento</Btn>}{x.kind==='bill'&&<Btn onClick={()=>openBill(bills.find(b=>b.id===x.id))}>Editar</Btn>}</RowActions>}]}/>:<Empty title="Nenhum título registrado" desc="Finalize vendas, receba compras ou cadastre uma conta manual." action={<Btn primary onClick={()=>openBill()}>Nova conta</Btn>}/>}</Block><Block title="Histórico de pagamentos" caption="Movimentações registradas no ERP">{scope.payments.length?<DataTable rows={[...scope.payments].reverse()} columns={[{name:'Data',cell:(x:any)=>dateShort(x.date)},{name:'Descrição',cell:(x:any)=>x.description},{name:'Movimento',cell:(x:any)=><Tag tone={x.direction==='Entrada'?'good':'bad'}>{x.direction}</Tag>},{name:'Valor',cell:(x:any)=><b>{money(x.amount)}</b>}]}/>:<Empty title="Sem pagamentos registrados" desc="Os recebimentos e pagamentos lançados aparecerão aqui."/>}</Block></>}
