   {modal==='conta'&&<div className="erp-form-grid"><EInput title="Descrição da conta" name="title" form={form} setForm={setForm} required/><EInput title="Tipo" name="type" form={form} setForm={setForm} options={[{value:'Pagar',label:'Conta a pagar'},{value:'Receber',label:'Conta a receber'}]}/><EInput title="Categoria" name="category" form={form} setForm={setForm}/><EInput title="Valor (R$)" name="amount" type="number" form={form} setForm={setForm} required/><EInput title="Data de lançamento" name="date" type="date" form={form} setForm={setForm}/><EInput title="Vencimento" name="dueDate" type="date" form={form} setForm={setForm}/>{!editingId&&<EInput title="Valor já pago (R$)" name="paid" type="number" form={form} setForm={setForm}/>}</div>}
